# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift
from hourglass.errors import ProjectError


def make_shift(worker, day, text):
    return Shift(worker, day, parse_span(text))


def busy_week():
    return [
        make_shift("Ana", "mon", "09:00-10:30"),
        make_shift("Ben", "mon", "09:00-17:00"),
        make_shift("Ben", "tue", "09:00-10:20"),
        make_shift("Ana", "tue", "09:00-10:00")
    ]


def tied_week():
    return [
        make_shift("Zed", "mon", "09:00-11:00"),
        make_shift("Amy", "mon", "09:00-10:00"),
        make_shift("Amy", "tue", "09:00-10:00"),
        make_shift("Bob", "mon", "09:00-11:00")
    ]


class TimesheetLinesTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        expected = ["Ben: 2 shifts, 9.3 hours", "Ana: 2 shifts, 2.5 hours"]
        self.assertEqual(timesheet_lines(busy_week()), expected)

    def test_ties_prefer_more_shifts_then_name(self):
        lines = timesheet_lines(tied_week())
        names = [line.split(":")[0] for line in lines]
        self.assertEqual(names, ["Amy", "Bob", "Zed"])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        shifts = [make_shift("  ", "tue", "09:00-10:00")]
        with self.assertRaises(ProjectError):
            timesheet_lines(shifts)


if __name__ == "__main__":
    unittest.main()
